import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.dexlib2.iface.instruction.*;import com.android.tools.smali.dexlib2.iface.reference.*;import java.io.*;
public class Dump {public static void main(String[] a)throws Exception{var z=DexFileFactory.loadDexContainer(new File(a[0]),Opcodes.getDefault());for(String e:z.getDexEntryNames())for(ClassDef c:z.getEntry(e).getDexFile().getClasses()){boolean match=false;for(int k=2;k<a.length;k++)if(c.getType().startsWith(a[k]))match=true;for(Method m:c.getMethods()){if(m.getImplementation()==null)continue;boolean found=match;if(a[1].equals("xref")){found=false;for(var ins:m.getImplementation().getInstructions())if(ins instanceof ReferenceInstruction r)for(int k=2;k<a.length;k++)if(r.getReference().toString().contains(a[k]))found=true;}if(!found)continue;System.out.println("METHOD "+m+" regs="+m.getImplementation().getRegisterCount());int i=0;for(var ins:m.getImplementation().getInstructions()){String line=(i++)+" "+ins.getOpcode();if(ins instanceof RegisterRangeInstruction r)line+=" {v"+r.getStartRegister()+"..+"+r.getRegisterCount()+"}";else if(ins instanceof FiveRegisterInstruction r)line+=" {"+r.getRegisterC()+","+r.getRegisterD()+","+r.getRegisterE()+","+r.getRegisterF()+","+r.getRegisterG()+"} #"+r.getRegisterCount();else if(ins instanceof TwoRegisterInstruction r)line+=" v"+r.getRegisterA()+",v"+r.getRegisterB();else if(ins instanceof OneRegisterInstruction r)line+=" v"+r.getRegisterA();if(ins instanceof ReferenceInstruction r)line+=" "+r.getReference();if(ins instanceof NarrowLiteralInstruction r)line+=" #"+r.getNarrowLiteral();if(!a[1].equals("xref")||ins instanceof ReferenceInstruction)System.out.println(line);}}}}}
